import { useEffect, useRef } from 'react'
import { LayoutChangeEvent, Text, View } from 'react-native'
import MaskedView from '@react-native-masked-view/masked-view'
import Animated, {
	LinearTransition,
	SharedValue,
	useSharedValue,
	useDerivedValue,
	useAnimatedStyle,
	withTiming,
	interpolate,
	Extrapolation,
	Easing,
	withSpring
} from 'react-native-reanimated'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import { REVEALING_TRANSCRIPT_ANIMATION_DURATION } from '@/constants'

type WordProps = {
	index: number
	word: string
	wordsRevealed: SharedValue<number>
}

const Word = ({ index, word, wordsRevealed }: WordProps) => {
	const { theme } = useTheme()
	const wordWidth = useSharedValue(0)

	const progress = useDerivedValue(() =>
		interpolate(
			wordsRevealed.get(),
			[index, index + 1],
			[0, 1],
			Extrapolation.CLAMP
		)
	)

	const maskStyle = useAnimatedStyle(() => ({
		width: wordWidth.get() * progress.get(),
		height: '100%',
		backgroundColor: colors[theme].background
	}))

	return (
		<MaskedView
			style={styles.maskedView}
			maskElement={<Animated.View style={maskStyle} />}
		>
			<View
				onLayout={(event: LayoutChangeEvent) => {
					wordWidth.set(event.nativeEvent.layout.width)
				}}
				style={styles.wordContainer}
			>
				<Text style={styles.wordText(theme)}>{word + ' '}</Text>
			</View>
		</MaskedView>
	)
}

export const RevealingTranscript = ({
	prompt,
	isTransferred,
	parentHeight
}: {
	prompt: string
	isTransferred: boolean
	parentHeight: number
}) => {
	const words = prompt.trim().split(/\s+/)

	const wordsRevealed = useSharedValue(0)

	const lastTargetRef = useRef(0)

	const WORD_REVEAL_DURATION = 250 // duration of word reveal
	const WORD_RESET_DURATION = 80 // duration of word reset if word changes

	useEffect(() => {
		const nextTarget = words.length
		const prevTarget = lastTargetRef.current

		// dont animate if word hasn't changed
		if (nextTarget === prevTarget) return

		if (nextTarget > prevTarget) {
			// animate word reveal since there is new text
			lastTargetRef.current = nextTarget
			wordsRevealed.set(
				withTiming(nextTarget, {
					duration: (nextTarget - prevTarget) * WORD_REVEAL_DURATION,
					easing: Easing.linear
				})
			)
		} else {
			// animate word reset since existing text has been changed/removed
			lastTargetRef.current = nextTarget
			wordsRevealed.set(
				withTiming(nextTarget, {
					duration: WORD_RESET_DURATION,
					easing: Easing.out(Easing.quad)
				})
			)
		}
	}, [wordsRevealed, words.length])

	const isSubmittedValue = useDerivedValue(() => isTransferred, [isTransferred])

	const slideUpStyle = useAnimatedStyle(() => ({
		transform: [
			{
				translateY: withSpring(isSubmittedValue.get() ? -parentHeight : 0, {
					duration: REVEALING_TRANSCRIPT_ANIMATION_DURATION,
					dampingRatio: 1.25
				})
			}
		]
	}))

	return (
		<Animated.View
			layout={LinearTransition.springify().damping(18).stiffness(140)}
			style={[styles.transcriptContainer, slideUpStyle]}
		>
			<View style={styles.wordsContainer}>
				{words.map((word, index) => (
					<Word
						key={`${index}-${word}`}
						index={index}
						word={word}
						wordsRevealed={wordsRevealed}
					/>
				))}
			</View>
		</Animated.View>
	)
}

const styles = defineStyles({
	maskedView: {
		alignSelf: 'flex-start'
	},
	wordContainer: {
		alignSelf: 'flex-start'
	},
	wordText: (theme: Theme) => ({
		fontSize: 28,
		fontWeight: '500',
		color: colors[theme].gray[900]
	}),
	transcriptContainer: {
		zIndex: 1
	},
	wordsContainer: {
		flexDirection: 'row',
		flexWrap: 'wrap'
	}
})
